#!/bin/bash
# Evaluate the visible train slice from artifacts generated by method/run_puma.py.
#
# Usage:
#   bash scripts/evaluate_train.sh [raw_results_json]

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

RAW_PATH="${1:-outputs/puma_reproduction/raw_results.json}"
python eval/train/evaluate_puma.py --raw "$RAW_PATH" --scores scoring/scores_train.json
